// Every location where the mineral occurs in this family, best chance first
inline std::vector<OreLocation> locationsFor(const std::string& mineral, MiningFamily family) {
    std::vector<OreLocation> out;
    for (const auto& row : ORE_LOCATIONS) {
        if (row.family == family && mineral == row.mineral) out.push_back(row);
    }
    std::sort(out.begin(), out.end(), [](const OreLocation& a, const OreLocation& b) { return a.chance > b.chance; });
    return out;
}

// The other way round: everything mined at one place, best chance first.
// A note that says [[Daymar]] wants this list, not the places for an ore.
inline std::vector<OreLocation> oresAt(const std::string& place, MiningFamily family) {
    std::vector<OreLocation> out;
    for (const auto& row : ORE_LOCATIONS) {
        if (row.family == family && _stricmp(row.location, place.c_str()) == 0) out.push_back(row);
    }
    std::sort(out.begin(), out.end(),
              [](const OreLocation& a, const OreLocation& b) { return a.chance > b.chance; });
    return out;
}

// The place as the table spells it, or "" when it knows no such place
inline std::string placeNamed(const std::string& name) {
    for (const auto& row : ORE_LOCATIONS) {
        if (_stricmp(row.location, name.c_str()) == 0) return row.location;
    }
    return "";
}

// The best mineral of a family at every location that has the family at all
inline std::vector<OreLocation> bestOfFamily(MiningFamily family) {
    std::vector<OreLocation> out;
    for (const auto& row : ORE_LOCATIONS) {
        if (row.family != family) continue;
        auto it = std::find_if(out.begin(), out.end(), [&](const OreLocation& o) { return std::string(o.location) == row.location; });
        if (it == out.end()) out.push_back(row);
        else if (row.chance > it->chance) *it = row;
    }
    std::sort(out.begin(), out.end(), [](const OreLocation& a, const OreLocation& b) { return a.chance > b.chance; });
    return out;
}

